import java.util.*;

public class LC236 {
    // ===== 递归解法（推荐） =====
    public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {
        if (root == null || root == p || root == q) return root;

        TreeNode left  = lowestCommonAncestor(root.left,  p, q);
        TreeNode right = lowestCommonAncestor(root.right, p, q);

        if (left != null && right != null) return root; // p、q 分居两侧
        return left != null ? left : right;             // 都在同一侧，往上传
    }

    // ===== 迭代解法：父指针 + HashSet =====
    public TreeNode lcaIterative(TreeNode root, TreeNode p, TreeNode q) {
        // 1. BFS 记录每个节点的父指针
        Map<TreeNode, TreeNode> parent = new HashMap<>();
        parent.put(root, null);
        Deque<TreeNode> queue = new ArrayDeque<>();
        queue.add(root);
        while (!parent.containsKey(p) || !parent.containsKey(q)) {
            TreeNode node = queue.poll();
            if (node.left  != null) { parent.put(node.left,  node); queue.add(node.left);  }
            if (node.right != null) { parent.put(node.right, node); queue.add(node.right); }
        }
        // 2. 从 p 向上走，把所有祖先加入集合
        Set<TreeNode> ancestors = new HashSet<>();
        TreeNode cur = p;
        while (cur != null) { ancestors.add(cur); cur = parent.get(cur); }
        // 3. 从 q 向上走，第一个出现在祖先集合中的就是 LCA
        cur = q;
        while (!ancestors.contains(cur)) cur = parent.get(cur);
        return cur;
    }

    // ===== 测试 =====
    public static void main(String[] args) {
        //       3
        //      / \
        //     5   1
        //    / \ / \
        //   6  2 0  8
        //     / \
        //    7   4
        TreeNode n3 = new TreeNode(3), n5 = new TreeNode(5), n1 = new TreeNode(1);
        TreeNode n6 = new TreeNode(6), n2 = new TreeNode(2);
        TreeNode n0 = new TreeNode(0), n8 = new TreeNode(8);
        TreeNode n7 = new TreeNode(7), n4 = new TreeNode(4);
        n3.left = n5; n3.right = n1;
        n5.left = n6; n5.right = n2;
        n1.left = n0; n1.right = n8;
        n2.left = n7; n2.right = n4;

        LC236 sol = new LC236();
        System.out.println(sol.lowestCommonAncestor(n3, n5, n1).val); // 3
        System.out.println(sol.lowestCommonAncestor(n3, n5, n4).val); // 5  (p 是 q 的祖先)
        System.out.println(sol.lcaIterative(n3, n5, n1).val);        // 3
    }
}

class TreeNode {
    int val;
    TreeNode left, right;
    TreeNode(int val) { this.val = val; }
}
